PTX_SOURCE = r"""
.version 7.1
.target sm_80
.address_size 64

.visible .entry avg_pool_kernel (
    .param .u64   input_ptr,
    .param .u64   output_ptr,
    .param .s32   batch,
    .param .s32   channels,
    .param .s32   in_len,
    .param .s32   kernel,
    .param .s32   stride,
    .param .s32   padding
)
{
    // --------------------
    // registers
    // --------------------
    .reg .pred   %p<4>;
    .reg .s32    %r<30>;
    .reg .u64    %rd<12>;
    .reg .f16    %fh0;
    .reg .f32    %fs0;
    .reg .f32    %fs_sum;

    // --------------------
    // load parameters
    // --------------------
    ld.param.u64    %rd1, [input_ptr];
    ld.param.u64    %rd2, [output_ptr];
    ld.param.s32    %r1,  [batch];
    ld.param.s32    %r2,  [channels];
    ld.param.s32    %r3,  [in_len];
    ld.param.s32    %r4,  [kernel];
    ld.param.s32    %r5,  [stride];
    ld.param.s32    %r6,  [padding];

    // --------------------
    // compute output length = (in_len + 2*pad - kernel)/stride + 1
    // --------------------
    mul.lo.s32      %r7,  %r6, 2;               // 2*pad
    add.s32         %r8,  %r3, %r7;            // in_len + 2*pad
    sub.s32         %r9,  %r8, %r4;            // - kernel
    div.s32         %r10, %r9, %r5;            // /(stride)
    add.s32         %r11, %r10, 1;             // +1  ==> out_len

    // --------------------
    // total output elements = batch * channels * out_len
    // --------------------
    mul.lo.s32      %r12, %r1, %r2;            // batch*channels
    mul.lo.s32      %r13, %r12, %r11;          // *out_len

    // --------------------
    // global thread id = blockIdx.x * blockDim.x + threadIdx.x
    // --------------------
    mov.u32         %r14, %ctaid.x;
    mov.u32         %r15, %ntid.x;
    mov.u32         %r16, %tid.x;
    mad.lo.s32      %r17, %r14, %r15, %r16;    // global index

    // early exit if out of range
    setp.ge.s32     %p0, %r17, %r13;
    @%p0 bra        DONE;

    // --------------------
    // decompose linear index into (b, c, out_idx)
    // out_idx = idx % out_len
    // tmp      = idx / out_len
    // c        = tmp % channels
    // b        = tmp / channels
    // --------------------
    div.s32         %r18, %r17, %r11;          // tmp = idx / out_len
    rem.s32         %r19, %r17, %r11;          // out_idx
    div.s32         %r20, %r18, %r2;           // b = tmp / channels
    rem.s32         %r21, %r18, %r2;           // c = tmp % channels

    // --------------------
    // compute start position in input: start = out_idx*stride - padding
    // --------------------
    mul.lo.s32      %r22, %r19, %r5;           // out_idx*stride
    sub.s32         %r23, %r22, %r6;           // -padding   => in_start

    // --------------------
    // pre‑compute base offset = (b*channels + c) * in_len
    // --------------------
    mad.lo.s32      %r24, %r20, %r2, %r21;     // b*channels + c
    mul.lo.s32      %r25, %r24, %r3;           // *in_len    => base_index

    // --------------------
    // accumulate sum in fp32
    // --------------------
    mov.f32         %fs_sum, 0f00000000;       // 0.0f

    // loop over kernel elements
    mov.s32         %r26, 0;                   // k = 0
LOOP_K:
    setp.ge.s32     %p1, %r26, %r4;            // if k >= kernel break
    @%p1 bra        END_LOOP;

    // pos = in_start + k
    add.s32         %r27, %r23, %r26;          // pos

    // if (pos < 0) skip
    setp.lt.s32     %p2, %r27, 0;
    @%p2 bra        SKIP_LOAD;

    // if (pos >= in_len) skip
    setp.ge.s32     %p3, %r27, %r3;
    @%p3 bra        SKIP_LOAD;

    // linear index = base_index + pos
    add.s32         %r28, %r25, %r27;          // idx_in
    // address = input_ptr + idx_in * sizeof(half) (2 bytes)
    cvt.u64.s32     %rd3, %r28;
    shl.b64         %rd4, %rd3, 1;             // *2
    add.u64         %rd5, %rd1, %rd4;          // final address

    // load half, convert to fp32, add to sum
    ld.global.nc.f16 %fh0, [%rd5];
    cvt.f32.f16     %fs0, %fh0;
    add.f32         %fs_sum, %fs_sum, %fs0;

SKIP_LOAD:
    add.s32         %r26, %r26, 1;             // k++
    bra.uni         LOOP_K;

END_LOOP:
    // compute average = sum / kernel
    cvt.f32.s32     %fs0, %r4;                 // kernel as fp32
    div.f32         %fs0, %fs_sum, %fs0;       // avg

    // convert back to half
    cvt.rn.f16.f32  %fh0, %fs0;

    // write output
    // out linear index = ((b*channels + c) * out_len) + out_idx
    mad.lo.s32      %r29, %r24, %r11, %r19;    // ((b*channels+c)*out_len)+out_idx
    cvt.u64.s32     %rd6, %r29;
    shl.b64         %rd7, %rd6, 1;             // *2 bytes
    add.u64         %rd8, %rd2, %rd7;
    st.global.f16   [%rd8], %fh0;

DONE:
    ret;
}
